    "kernel_code": "1: \"\"\"Elementwise real cube root with a polynomial seed and Newton correction.\n2: \n3: Original synthetic Triton implementation, not an upstream bug reproduction.\n4: \"\"\"\n5: import torch\n6: import triton\n7: import triton.language as tl\n8: \n9: \n10: @triton.jit\n11: def _cbrt_kernel(X, OUT, N: tl.constexpr, BLOCK: tl.constexpr):\n12:     index = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)\n13:     active = index < N\n14:     x = tl.load(X + index, mask=active, other=0.0).to(tl.float32)\n15:     magnitude = tl.abs(x)\n16:     safe = tl.where(magnitude == 0.0, 1.0, magnitude)\n17:     encoding = safe.to(tl.uint32, bitcast=True)\n18:     exponent = ((encoding >> 23) & 255).to(tl.int32) - 127\n19:     mantissa = ((encoding & 0x007fffff) | 0x3f800000).to(tl.float32, bitcast=True)\n20:     quotient = (exponent + 24) // 3 - 8\n21:     remainder = exponent - 3 * quotient\n22:     estimate = -0.06 * mantissa + 0.439\n23:     estimate = estimate * mantissa + 0.622\n24:     estimate = (2.0 * estimate + tl.div_rn(mantissa, estimate * estimate)) * (1.0 / 3.0)\n25:     remainder_scale = tl.where(remainder == 0, 1.0,\n26:                               tl.where(remainder == 1, 1.2599210498948732, 1.5874010519681994))\n27:     scale = ((quotient + 127).to(tl.uint32) << 23).to(tl.float32, bitcast=True)\n28:     value = (estimate * remainder_scale) * scale\n29:     value = tl.where(x < 0.0, -value, value)\n30:     value = tl.where(magnitude == 0.0, x, value)\n31:     tl.store(OUT + index, value, mask=active)\n32: \n33: \n34: def validate_inputs(x, require_cuda=True):\n35:     \"\"\"Validate the complete public domain; also usable on CPU.\"\"\"\n36:     def require(condition, message):\n37:         if not condition:\n38:             raise ValueError(message)\n39: \n40:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n41:     require(type(x) is torch.Tensor, \"ordinary torch.Tensor required\")\n42:     require(x.layout == torch.strided and x.is_contiguous(),\n43:             \"contiguous strided input required\")\n44:     require(not x.requires_grad and not x.is_inference(),\n45:             \"ordinary non-gradient input required\")\n46:     require(not x.is_neg() and not x.is_conj(),\n47:             \"logical view flags are outside this domain\")\n48:     require(not require_cuda or x.is_cuda, \"CUDA input required by run\")\n49:     require(x.ndim == 1 and 1 <= x.numel() <= 131072,\n50:             \"x must have shape [N] with N in [1,131072]\")\n51:     require(x.dtype == torch.float16, \"FP16 input required\")\n52:     require(bool((torch.isfinite(x)).all().item()),\n53:             \"all input values must be finite\")\n54:     return {\"valid\": True, \"size\": x.numel()}\n55: \n56: \n57: def run(x):\n58:     \"\"\"Return a fresh FP32 tensor approximating the real cube root of x.\"\"\"\n59:     validate_inputs(x)\n60:     n = x.numel()\n61:     with torch.cuda.device(x.device):\n62:         output = torch.empty((n,), dtype=torch.float32, device=x.device)\n63:         _cbrt_kernel[(triton.cdiv(n, 256),)](\n64:             x, output, N=n, BLOCK=256, num_warps=4, enable_fp_fusion=False)\n65:     return output\n66: \n67: \n68: def reference(x):\n69:     \"\"\"Evaluate the real cube root using the FP64 power library.\"\"\"\n70:     validate_inputs(x, require_cuda=False)\n71:     value = x.to(torch.float64)\n72:     return torch.sign(value) * torch.pow(torch.abs(value), 1.0 / 3.0)\n73: \n74: \n75: def make_inputs(device=\"cuda\", size=4093, seed=0):\n76:     \"\"\"Convenience examples only; all finite FP16 values are legal.\"\"\"\n77:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n78:     x = (128.0 * torch.rand((size,), generator=generator) - 64.0).to(torch.float16)\n79:     return (x.to(device),)",
